//  QS_13_ConnorsRSI - BACKTEST RESEARCH STRATEGY. Rules: backtest/rules.yaml (frozen 2026-10-17),
//  the original IBSFade indicator's own classification. Home frame: Day bars. Generated by
//  backtest/gen_strategies.py - do not edit by hand.
//  Part of ninjatrader_quant_indicators
//
//  DISCLAIMER
//  This software is provided for educational and informational purposes only.
//  It is NOT financial, investment, or trading advice, and nothing it computes
//  or draws is a recommendation to buy or sell any instrument. Trading futures
//  and other leveraged products carries a substantial risk of loss and is not
//  suitable for every investor. Past performance is not indicative of future
//  results. You are solely responsible for any decision you make. See
//  DISCLAIMER.md in the repository root.
//
//  The indicator logic below is transplanted unchanged from QI_13_ConnorsRSI (indicators/QI_13_ConnorsRSI.cs);
//  its own documentation follows.
//
//  QI_13_ConnorsRSI - Connors RSI (RSI(2) + streak RSI(2) + 100-bar ROC percentile)
//
//  Lineage : split out of the "IBSFade" multi-strategy indicator, DataBox plot #3
//            (ORIG lines 342, 410-411, 1552-1568, 1277-1296).
//  Provenance: Deviates from Connors Research's published CRSI, which uses RSI(3) of price and resets the
//            streak to 0 on an unchanged close; this file keeps the original indicator's RSI(2) and
//            streak-carrying rule by the user's decision (validation/channel-a-algo-1.md M3).
//  Concept : ConnorsRSI, Connors Research (2012).
//  Formula : CRSI = ( RSI(Close,2,1) + RSI(streak,2,1) + PercentRank(ROC1, 100) ) / 3
//            streak  : signed run of up/down closes (+n up, -n down); an unchanged
//                      close keeps the current counts (ORIG 1555-1568).
//            PercentRank : share of the last min(100, CurrentBar) one-bar changes
//                      that are strictly below today's Close[0] - Close[1].
//  Quirks  : (1) Value is 50 until CurrentBar >= 100 (ORIG 1278-1279).
//            (2) pastRoc uses ORIG's exact indexing at 1288:
//                Close[i] - (i + 1 < CurrentBar ? Close[i + 1] : Close[i])
//                so the oldest sample can degrade to 0 when i + 1 == CurrentBar.
//            (3) The streak update (ORIG 1552-1568) is executed every bar BEFORE
//                the value is computed, as ORIG calls UpdateNewAlphas() first.
//            (4) ORIG's module-wide warm-up gate (CurrentBar < 50 at ORIG 601) is
//                preserved, so streak counting starts at bar 50 as in ORIG on daily
//                charts. On INTRADAY charts ORIG's gate also waits for its hidden
//                daily series (CurrentBars[1] < 1 at ORIG 537), i.e. until the second
//                daily bar; this standalone does not add that series, so on intraday
//                charts its streak memory starts earlier and CRSI can differ from
//                ORIG for roughly the oldest day of history before converging.
// ============================================================================
#region Using declarations
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.ComponentModel.DataAnnotations;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Input;
using System.Windows.Media;
using System.Xml.Serialization;
using NinjaTrader.Cbi;
using NinjaTrader.Gui;
using NinjaTrader.Gui.Chart;
using NinjaTrader.Gui.SuperDom;
using NinjaTrader.Gui.Tools;
using NinjaTrader.Data;
using NinjaTrader.NinjaScript;
using NinjaTrader.Core.FloatingPoint;
using NinjaTrader.NinjaScript.Indicators;
using NinjaTrader.NinjaScript.DrawingTools;
#endregion

// This namespace holds Strategies in this folder and is required. Do not change it.
namespace NinjaTrader.NinjaScript.Strategies
{
	public class QS_13_ConnorsRSI : Strategy
	{
		private RSI				rsi2;
		private RSI				rsiStreak;
		private Series<double>	streakSeries;
		private int				consecUpDays;
		private int				consecDownDays;
		private bool			disclaimerDrawn;

		protected override void OnStateChange()
		{
			if (State == State.SetDefaults)
			{
				Description					= "ConnorsRSI: average of RSI(Close,2,1), RSI(streak,2,1) and the 100-bar "
											+ "percent rank of the 1-bar change; 50 until 100 bars are available. "
											+ "Reference lines at 15 / 85 are neutral boundaries only. "
											+ "Educational use only - not financial advice."
											+ " Backtest research strategy generated from QI_13_ConnorsRSI and backtest/rules.yaml. Not financial advice. Places no orders in real time unless Backtest Only is turned off.";
				Name						= "QS_13_ConnorsRSI";
				Calculate					= Calculate.OnBarClose;
				// Strategy defaults (backtest research; generated)
				EntriesPerDirection			= 1;
				EntryHandling				= EntryHandling.AllEntries;
				IsExitOnSessionCloseStrategy = false;
				StartBehavior				= StartBehavior.WaitUntilFlat;
				BarsRequiredToTrade			= 0;
				Slippage					= 1;
				DefaultQuantity				= 1;
				BacktestOnly				= true;
				TraceOrders					= false;
				IsOverlay					= false;
				DisplayInDataBox			= true;
				DrawOnPricePanel			= false;
				ScaleJustification			= ScaleJustification.Right;

				LowerThreshold				= 15;
				UpperThreshold				= 85;
				ShowDisclaimer				= false;

				AddPlot(new Stroke(Brushes.Goldenrod, 2), PlotStyle.Line, "ConnorsRSI");
				AddLine(Brushes.DodgerBlue, 15, "Lower Threshold");
				AddLine(Brushes.OrangeRed,  85, "Upper Threshold");
			}
			else if (State == State.Configure)
			{
				// BacktestOnly: never let NinjaTrader synchronise the account with its own orders (BT16).
				if (BacktestOnly)
					StartBehavior = StartBehavior.WaitUntilFlat;
				Lines[0].Value = LowerThreshold;
				Lines[1].Value = UpperThreshold;
			}
			else if (State == State.DataLoaded)
			{
				// ORIG 342, 406-407, 410-411
				consecDownDays	= 0;
				consecUpDays	= 0;
				rsi2			= RSI(Close, 2, 1);
				streakSeries	= new Series<double>(this);
				rsiStreak		= RSI(streakSeries, 2, 1);
				disclaimerDrawn	= false;
			}
		}

		private void QiUpdate()
		{
			// ORIG module-wide warm-up gate (ORIG 537 / 601).
			if (CurrentBar < 50)
				return;

			// Streak series update - ORIG 1552-1568, runs every bar before the value calc.
			UpdateStreak();

			// ORIG 1277-1294
			double crsiVal = 50;
			if (CurrentBar >= 100)
			{
				double rsiP = rsi2[0];
				double rsiS = rsiStreak[0];
				double tRoc = Close[0] - Close[1];
				int below = 0;
				int total = Math.Min(100, CurrentBar);
				for (int i = 1; i <= total; i++)
				{
					double pRoc = Close[i] - (i + 1 < CurrentBar ? Close[i + 1] : Close[i]);
					if (pRoc < tRoc) below++;
				}
				double pRank = (double)below / total * 100.0;
				crsiVal = (rsiP + rsiS + pRank) / 3.0;
			}
			Values[0][0] = crsiVal;

			DrawDisclaimerOnce();
		}

		// ------------------------------------------------------------------------------
		//  Backtest rule (generated from backtest/rules.yaml - do not edit by hand)
		//  module ConnorsRSI | frame D | value connors_rsi = CRSI[0] | ORIG lines 1278-1296
		//  long : x < 15
		//  short: x > 85
		// ------------------------------------------------------------------------------
		protected override void OnBarUpdate()
		{
			QiUpdate();
			ApplyRule();
		}

		// Backtest-only safety (validation/channel-a-backtest.md BT16): a Realtime-only guard is not
		// enough - an order submitted on the last historical bar carries into real time, and the
		// account-synchronising start behaviours make NinjaTrader place its own orders. With
		// BacktestOnly on, orders are allowed only during historical processing, only on the
		// Strategy Analyzer 'Backtest' account or a Sim/Playback account, and never on the last two
		// historical bars of a non-Backtest account; StartBehavior is forced to WaitUntilFlat.
		private bool OrdersAllowed()
		{
			if (State != State.Historical) return false;
			string acct = Account != null ? Account.Name : string.Empty;
			bool backtest = acct == "Backtest";
			bool research = backtest || acct.StartsWith("Sim") || acct.StartsWith("Playback");
			if (!research) return false;
			if (!backtest && CurrentBars[0] >= BarsArray[0].Count - 2) return false;
			return true;
		}

		private void ApplyRule()
		{
			if (BacktestOnly && !OrdersAllowed()) return;
			if (BarsInProgress != 0) return;

			double x = double.NaN;
			if (CRSI.IsValidDataPoint(0))
				x = CRSI[0];

			// A NaN / unset value maps to a flat target.
			int target = 0;
			if (!double.IsNaN(x))
			{
				bool goLong  = x < 15.0;
				bool goShort = x > 85.0;
				if (goLong)
					target = 1;
				else if (goShort)
					target = -1;
			}

			if (target == 1 && Position.MarketPosition != MarketPosition.Long)
				EnterLong(DefaultQuantity, "QS_L");
			else if (target == -1 && Position.MarketPosition != MarketPosition.Short)
				EnterShort(DefaultQuantity, "QS_S");
			else if (target == 0)
			{
				if (Position.MarketPosition == MarketPosition.Long)
					ExitLong("QS_XL", "QS_L");
				else if (Position.MarketPosition == MarketPosition.Short)
					ExitShort("QS_XS", "QS_S");
			}
		}

		// ORIG 1552-1568 (streak part of UpdateNewAlphas)
		private void UpdateStreak()
		{
			if (CurrentBar < 1) { streakSeries[0] = 0; return; }
			if (Close[0] > Close[1])
			{
				consecUpDays++;
				consecDownDays = 0;
			}
			else if (Close[0] < Close[1])
			{
				consecDownDays++;
				consecUpDays = 0;
			}
			// else: unchanged, keep counts

			streakSeries[0] = consecUpDays > 0 ? consecUpDays : -consecDownDays;
		}

		private void DrawDisclaimerOnce()
		{
			if (!ShowDisclaimer || disclaimerDrawn)
				return;

			Draw.TextFixed(this, "QI_Disclaimer", "Educational use only - not financial advice",
				TextPosition.BottomLeft, Brushes.Gray, new SimpleFont("Arial", 9),
				Brushes.Transparent, Brushes.Transparent, 0);
			disclaimerDrawn = true;
		}

		public override string DisplayName
		{
			get { return "QS 13 ConnorsRSI"; }
		}

		#region Properties

		[NinjaScriptProperty]
		[Display(Name = "Backtest Only", Order = 0, GroupName = "Safety")]
		public bool BacktestOnly { get; set; }

		[NinjaScriptProperty]
		[Range(0, 100)]
		[Display(Name = "Lower Threshold", Description = "Reference line only. Original default 15.",
			Order = 1, GroupName = "Parameters")]
		public double LowerThreshold { get; set; }

		[NinjaScriptProperty]
		[Range(0, 100)]
		[Display(Name = "Upper Threshold", Description = "Reference line only. Original default 85.",
			Order = 2, GroupName = "Parameters")]
		public double UpperThreshold { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Show Disclaimer", Description = "Draw the educational-use disclaimer on the chart.",
			Order = 1, GroupName = "Display")]
		public bool ShowDisclaimer { get; set; }

		/// <summary>Plotted ConnorsRSI value (0..100; 50 during warm-up).</summary>
		[Browsable(false)]
		[XmlIgnore]
		public Series<double> CRSI
		{
			get { return Values[0]; }
		}

		/// <summary>Non-plot signed streak series fed into the streak RSI (+n up closes, -n down closes).</summary>
		[Browsable(false)]
		[XmlIgnore]
		public Series<double> Streak
		{
			get { return streakSeries; }
		}

		#endregion
	}
}
